# flood exterior zero using 4-connectivity
ext=set(); q=deque()
for r in range(H):
 for c in range(W):
  if (r in (0,H-1) or c in (0,W-1)) and g[r][c]==0 and (r,c) not in ext:
   ext.add((r,c)); q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<H and 0<=nc<W and g[nr][nc]==0 and (nr,nc) not in ext:
   ext.add((nr,nc));q.append((nr,nc))
# 4-connected one-components; select if bordering enclosed zero
seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if g[r][c]==1 and (r,c) not in seen:
   comp={(r,c)};seen.add((r,c));q=deque([(r,c)])
   while q:
    x,y=q.popleft()
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     xx,yy=x+dx,y+dy
     if 0<=xx<H and 0<=yy<W and g[xx][yy]==1 and (xx,yy) not in seen:
      seen.add((xx,yy));comp.add((xx,yy));q.append((xx,yy))
   touches_hole=False
   for x,y in comp:
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     xx,yy=x+dx,y+dy
     if 0<=xx<H and 0<=yy<W and g[xx][yy]==0 and (xx,yy) not in ext: touches_hole=True
   rs=[p[0] for p in comp];cs=[p[1] for p in comp]
   comps.append((touches_hole, (min(rs),max(rs),min(cs),max(cs)),comp))
print('components',[(a,b,len(c)) for a,b,c in comps])
out=[row[:] for row in g]
for selected,bbox,comp in comps:
 if selected:
  for r,c in comp:
   for dr in (-1,0,1):
    for dc in (-1,0,1):
     rr,cc=r+dr,c+dc
     if 0<=rr<H and 0<=cc<W and g[rr][cc]==0:
      out[rr][cc]=2 if (rr,cc) in ext else 3
print('\n'.join(' '.join(map(str,row)) for row in out))
print('counts', {v:sum(x==v for row in out for x in row) for v in (0,1,2,3)})
